const sources = [
  {source:'GameSpot',  url:'https://www.gamespot.com/feeds/news'},
  {source:'Kotaku',    url:'https://kotaku.com/feed'},
  {source:'PCGamer',   url:'https://www.pcgamer.com/rss/'},
  {source:'Polygon',   url:'https://www.polygon.com/rss/polygon-archives/index.xml'},
  {source:'Eurogamer', url:'https://www.eurogamer.net/feed'},
  {source:'VG247',     url:'https://www.vg247.com/feed'},
  {source:'Gematsu',   url:'https://www.gematsu.com/feed'},
  {source:'XboxWire',  url:'https://news.xbox.com/en-us/feed/'},
  {source:'GamesPress',url:'https://www.gamespress.com/en-gb/News/RSS'}
];

const message_id = $items()[0].json.result.message_id;

return sources.map((item, index) => {
  return {
    json: {
      ...item,
      message_id: message_id,
      itemIndex: index
    }
  };
});

const parentData = $items('Split Sources')[0].json;

if (items.length === 0) {
  return [{ json: { ...parentData, success: false } }];
}

return items.map((article) => {
  return {
    json: {
      ...article.json,
      source: parentData.source,
      message_id: parentData.message_id,
      itemIndex: parentData.itemIndex,
      success: true,
    },
  };
});

const parentData = $items('Split Sources')[0].json;

const anySuccess = items.some(i => i.json && i.json.success === true);

return [{
  json: {
    source: parentData.source,
    success: anySuccess,
    message_id: parentData.message_id,
    itemIndex: parentData.itemIndex
  }
}];

// This node now receives a complete list of all articles from the Merge node.
// No need for $items() anymore.
const allItems = items;

const firstValidItem = allItems.find(i => i.json && i.json.message_id);
const messageId = firstValidItem ? firstValidItem.json.message_id : null;

const validArticles = allItems.filter(i => i.json && i.json.success && i.json.title);

const seen = new Set();
const uniqueArticles = validArticles.filter(item => {
  const key = item.json.link || item.json.title;
  if (seen.has(key)) {
    return false;
  } else {
    seen.add(key);
    return true;
  }
});

const finalArticles = uniqueArticles.map(item => {
  const json = item.json;
  return {
    title: json.title || "بدون عنوان",
    link: json.link || "#",
    source: json.source || "نامشخص",
    rawContent: json.contentSnippet || json.content || ""
  };
});

return [{
  json: {
    articles: finalArticles,
    messageId: messageId
  }
}];

// انتظار داریم این نود بعد از "Get Recent Posts" اجرا شود.
const data = $json || {};
const results = Array.isArray(data.results) ? data.results : [];

const tagScores = {};
const categoryScores = {};
const TOTAL_WEIGHT_VIEWS = 1;
const TOTAL_WEIGHT_LIKES = 10;
const TOTAL_WEIGHT_COMMENTS = 20;

for (const post of results) {
  const views = Number(post.views_count || 0);
  const likes = Number(post.likes_count || 0);
  const comments = Number(post.comments_count || 0);
  const score = views * TOTAL_WEIGHT_VIEWS + likes * TOTAL_WEIGHT_LIKES + comments * TOTAL_WEIGHT_COMMENTS;

  if (Array.isArray(post.tags)) {
    for (const tag of post.tags) {
      const key = tag.slug || tag.name || '';
      if (!key) continue;
      tagScores[key] = (tagScores[key] || 0) + score;
    }
  }

  const cat = post.category;
  if (cat) {
    categoryScores[cat] = (categoryScores[cat] || 0) + score;
  }
}

function topEntries(obj, limit = 5) {
  return Object.entries(obj)
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit)
    .map(([key, score]) => ({ key, score }));
}

const topTags = topEntries(tagScores, 7);
const topCategories = topEntries(categoryScores, 5);

const lines = [];
if (topTags.length) {
  lines.push('تگ‌های پربازدید اخیر:');
  for (const t of topTags) {
    lines.push(`- ${t.key} (امتیاز تقریبی: ${t.score})`);
  }
  lines.push('');
}

if (topCategories.length) {
  lines.push('دسته‌بندی‌های پربازدید اخیر:');
  for (const c of topCategories) {
    lines.push(`- ${c.key} (امتیاز تقریبی: ${c.score})`);
  }
  lines.push('');
}

if (!lines.length) {
  lines.push('داده کافی برای تحلیل سئو وجود ندارد.');
}

return [{
  json: {
    seo_insights: {
      top_tags: topTags,
      top_categories: topCategories
    },
    seo_summary_text: lines.join('\n')
  }
}];

const seo = $json || {};

return [{
  json: {
    memory_context: {
      seo_summary_text: seo.seo_summary_text || '',
      seo_insights: seo.seo_insights || {}
    }
  }
}];

