let { summary_markdown, seo_description } = $json;

// --- NEW: اگر summary_markdown اشتباهاً داخل ```json ...``` یک JSON کامل بود، استخراج و جایگزین کن
function unwrapJsonFromMarkdownFence(s) {
  if (typeof s !== 'string') return null;

  const trimmed = s.trim();

  // حالت: کل متن داخل کدبلاک ```json ... ```
  const fenced = trimmed.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
  const candidate = (fenced ? fenced[1] : trimmed).trim();

  // اگر candidate خودش یک آبجکت JSON بود، همون رو parse کن
  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) return null;

  const jsonText = candidate.slice(start, end + 1);

  try {
    const obj = JSON.parse(jsonText);
    // اگر خروجی AI این ساختار رو داشت، فیلدها رو اصلاح کن
    if (obj && typeof obj === 'object') {
      return obj;
    }
  } catch (e) {
    return null;
  }
  return null;
}

const extracted = unwrapJsonFromMarkdownFence(summary_markdown);
if (extracted) {
  // اگر AI اشتباهاً JSON رو گذاشته تو summary_markdown، فیلدها رو ازش بیرون بکش
  summary_markdown = extracted.summary_markdown ?? summary_markdown;
  seo_description = extracted.seo_description ?? seo_description;
  // اگر title/seo_title/tags/... هم اومده بود، روی item هم اعمالش کن
  for (const k of [
    'title','title_variants','excerpt','seo_title','category_slug','series_slug',
    'tags','focus_keywords','chosen_index','reason','selection_reason'
  ]) {
    if (extracted[k] !== undefined) $json[k] = extracted[k];
  }
}

// --- ORIGINAL LOGIC
function cleanUrl(u) {
  try {
    const url = new URL(u);
    const badParams = ['utm_source','utm_medium','utm_campaign','utm_term','utm_content','fbclid','gclid','ref'];
    badParams.forEach(p => url.searchParams.delete(p));
    return url.toString();
  } catch (e) {
    return u;
  }
}

summary_markdown = summary_markdown || '';
seo_description = seo_description || '';

const urlRegex = /(https?:\/\/[^\s)]+[^\s)\.,!?])/g;
summary_markdown = summary_markdown.replace(urlRegex, (m) => cleanUrl(m));
seo_description = seo_description.replace(urlRegex, (m) => cleanUrl(m));

const ytRegex = /(https?:\/\/(?:www\.)?(?:youtube\.com\/watch\?v=|youtu\.be\/)([A-Za-z0-9_-]{6,}))/g;
summary_markdown = summary_markdown.replace(ytRegex, (match, url, vid) => {
  const id = vid;
  return `\n<iframe width="560" height="315" src="https://www.youtube.com/embed/${id}" frameborder="0" allowfullscreen></iframe>\n`;
});

const textForLang = (summary_markdown || seo_description || '').slice(0, 1000);
const hasArabic = /[\u0600-\u06FF]/.test(textForLang);
const lang = hasArabic ? 'fa' : 'en';

return [{
  json: {
    ...$json,
    summary_markdown,
    seo_description,
    lang
  }
}];

const fetched = $items("Fetch Original Article HTML1")[0].json;

// html
const body = fetched.body || fetched.data || fetched;
const text = typeof body === "string" ? body : JSON.stringify(body);

// base url
const baseUrl =
  fetched.url ||
  fetched.pageUrl ||
  fetched.source_url ||
  fetched.sourceUrl ||
  fetched.post?.source_url ||
  fetched.post?.sourceUrl ||
  "";

// ---- helpers ----
const absolutize = (src) => {
  try {
    if (!src) return "";
    let s = String(src).trim();
    if (!s) return "";
    if (s.includes("<%") || s.includes("%>")) return "";
    if (s.startsWith("data:")) return "";
    if (s.startsWith("blob:")) return "";
    if (s.startsWith("javascript:")) return "";
    if (s.startsWith("mailto:")) return "";
    if (s.startsWith("tel:")) return "";
    if (s.startsWith("//")) s = "https:" + s;

    if (!/^https?:\/\//i.test(s)) {
      if (!baseUrl) return "";
      s = new URL(s, baseUrl).toString();
    }

    if (s.includes("scorecardresearch.com")) return "";
    return s;
  } catch {
    return "";
  }
};

const pickBestFromSrcset = (srcset) => {
  const parts = String(srcset)
    .split(",")
    .map((x) => x.trim().split(/\s+/)[0])
    .filter(Boolean);
  return parts.length ? parts[parts.length - 1] : "";
};

const uniq = (arr) => {
  const seen = new Set();
  return arr.filter((u) => (u && !seen.has(u) ? (seen.add(u), true) : false));
};

const getExtFromUrl = (u) => {
  try {
    const clean = u.split("?")[0].split("#")[0];
    const m = clean.match(/\.([a-z0-9]+)$/i);
    const ext = (m?.[1] || "jpg").toLowerCase();
    if (!["jpg", "jpeg", "png", "webp", "avif", "gif", "bmp", "tiff"].includes(ext)) return "jpg";
    return ext === "jpeg" ? "jpg" : ext;
  } catch {
    return "jpg";
  }
};

const slugifyEn = (s) => {
  const str = String(s || "").trim().toLowerCase();
  let out = str
    .replace(/&/g, " and ")
    .replace(/[^a-z0-9\s-]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/\s/g, "-")
    .replace(/-+/g, "-");

  out = out
    .split("-")
    .filter((w) => w && !["the", "a", "an", "of", "to", "in", "on", "for", "and"].includes(w))
    .join("-");

  return out || "";
};

const pad2 = (n) => String(n).padStart(2, "0");

const safeText = (s) =>
  String(s || "")
    .replace(/\s+/g, " ")
    .trim();

const stripTags = (html) =>
  String(html || "")
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, " ")
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, " ")
    .replace(/<\/?[^>]+>/g, " ");

const decodeEntitiesLite = (s) =>
  String(s || "")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">");

// ✅ NEW: helpers برای استخراج عنوان مقاله از HTML هم
const pickFirst = (...vals) => {
  for (const v of vals) {
    if (v === null || v === undefined) continue;
    if (typeof v === "string" && !v.trim()) continue;
    return v;
  }
  return "";
};

const parseHtmlTitle = (html) => {
  const m = /<title[^>]*>([\s\S]*?)<\/title>/i.exec(String(html || ""));
  return m?.[1] || "";
};

const parseMetaTitle = (html) => {
  const h = String(html || "");
  const m =
    /<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)["'][^>]*>/i.exec(h) ||
    /<meta[^>]+name=["']twitter:title["'][^>]+content=["']([^"']+)["'][^>]*>/i.exec(h);
  return m?.[1] || "";
};

const parseFirstH1 = (html) => {
  const m = /<h1\b[^>]*>([\s\S]*?)<\/h1>/i.exec(String(html || ""));
  return m?.[1] || "";
};

const sanitizeHeadingForHint = (h) => {
  const t = safeText(decodeEntitiesLite(stripTags(h))).slice(0, 80);
  // برای filename، فقط نسخه انگلیسی ساده نگه می‌داریم (فارسی را در alt نگه می‌داریم)
  const en = t
    .toLowerCase()
    .replace(/&/g, " and ")
    .replace(/[^a-z0-9\s-]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/\s/g, "-")
    .replace(/-+/g, "-");
  return en || "";
};

const getUrlHint = (url) => {
  try {
    const u = new URL(url);
    const last = u.pathname.split("/").filter(Boolean).pop() || "";
    const base = last.split(".")[0] || "";
    // حذف id عددی ابتدای اسم (مثل 4583334-foo)
    const cleaned = base.replace(/^[0-9]+-/, "");
    const hint = cleaned
      .toLowerCase()
      .replace(/%[0-9a-f]{2}/gi, "-")
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/-+/g, "-")
      .replace(/^-|-$/g, "")
      .slice(0, 40);
    return hint || "";
  } catch {
    return "";
  }
};

const getNearContext = (full, pos, beforeLen = 220, afterLen = 220) => {
  const start = Math.max(0, pos - beforeLen);
  const end = Math.min(full.length, pos + afterLen);
  const before = safeText(decodeEntitiesLite(stripTags(full.slice(start, pos))));
  const after = safeText(decodeEntitiesLite(stripTags(full.slice(pos, end))));
  return {
    contextBefore: before.slice(-180),
    contextAfter: after.slice(0, 180),
  };
};

const findNearestHeading = (full, pos) => {
  // پنجره‌ی قبل از تصویر
  const windowStart = Math.max(0, pos - 4000);
  const chunk = full.slice(windowStart, pos);

  // آخرین H2/H3/H1 نزدیک را پیدا کن
  const headingRegex = /<(h1|h2|h3)\b[^>]*>([\s\S]*?)<\/\1>/gi;
  let m;
  let last = null;
  while ((m = headingRegex.exec(chunk)) !== null) last = m;

  if (!last) return { nearestHeading: "", nearestHeadingLevel: "" };

  const level = (last[1] || "").toLowerCase();
  const raw = last[2] || "";
  const clean = safeText(decodeEntitiesLite(stripTags(raw)));

  return { nearestHeading: clean, nearestHeadingLevel: level };
};

// ---- derive postSlug & title/titleFromInputs ----
// مهم: title/slug ممکنه داخل post یا data باشد
const inputSlug =
  $json.slug ||
  $json.post?.slug ||
  $json.data?.slug ||
  $json.item?.slug ||
  "";

// ✅ UPDATED: عنوان را هم از JSON هم از HTML استخراج کن
const inputTitle = pickFirst(
  $json.title,
  $json.post?.title,
  $json.data?.title,
  $json.item?.title,

  // fallback از داخل HTML:
  safeText(decodeEntitiesLite(stripTags(parseMetaTitle(text)))),
  safeText(decodeEntitiesLite(stripTags(parseHtmlTitle(text)))),
  safeText(decodeEntitiesLite(stripTags(parseFirstH1(text))))
);

// اگر slug خراب/ناقص بود، از عنوان انگلیسی slug بساز
let postSlug = inputSlug && !/^a(-a)+$/i.test(inputSlug) ? inputSlug : "";
if (!postSlug) postSlug = slugifyEn(inputTitle);

// fallback اگر هیچی نبود
if (!postSlug) {
  const d = new Date();
  postSlug = `post-${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
}

const titleForAlt = safeText(inputTitle) || postSlug.replace(/-/g, " ");

// ---- IMAGES extraction (با کانتکست/heading/alt) ----
const metaImageRegexes = [
  /<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["'][^>]*>/i,
  /<meta[^>]+name=["']twitter:image["'][^>]+content=["']([^"']+)["'][^>]*>/i,
  /"thumbnailUrl"\s*:\s*"([^"]+)"/i,
  /"image"\s*:\s*\{[^}]*"url"\s*:\s*"([^"]+)"/i,
];

let mainImage = "";
for (const r of metaImageRegexes) {
  const m = r.exec(text);
  const u = absolutize(m?.[1]);
  if (u && !u.toLowerCase().includes("/blank_")) {
    mainImage = u;
    break;
  }
}

const imgTagRegex = /<img\b[^>]*>/gi;
const found = []; // {url, pos, srcAlt, srcTitle, nearestHeading...}
let tag;
while ((tag = imgTagRegex.exec(text)) !== null) {
  const imgTagHtml = tag[0];
  const pos = tag.index ?? 0;

  const getAttr = (name) => {
    const re = new RegExp(`${name}\\s*=\\s*["']([^"']+)["']`, "i");
    return re.exec(imgTagHtml)?.[1] || "";
  };

  let cand =
    getAttr("src") ||
    getAttr("data-src") ||
    pickBestFromSrcset(getAttr("srcset")) ||
    pickBestFromSrcset(getAttr("data-srcset"));

  cand = absolutize(cand);
  if (!cand) continue;

  const lower = cand.toLowerCase();
  if (lower.includes("/blank_")) continue;

  if (
    lower.includes("sprite") ||
    lower.includes("icon") ||
    lower.includes("tracking") ||
    lower.includes("pixel") ||
    lower.includes("beacon")
  ) continue;

  if (/\.(svg|ico)(\?|#|$)/i.test(cand)) continue;

  const srcAlt = safeText(decodeEntitiesLite(getAttr("alt")));
  const srcTitle = safeText(decodeEntitiesLite(getAttr("title")));

  const { nearestHeading, nearestHeadingLevel } = findNearestHeading(text, pos);
  const { contextBefore, contextAfter } = getNearContext(text, pos);

  found.push({
    url: cand,
    pos,
    srcAlt,
    srcTitle,
    nearestHeading,
    nearestHeadingLevel,
    contextBefore,
    contextAfter,
  });
}

// Deduplicate by URL but keep earliest pos + best metadata
const byUrl = new Map();
for (const f of found) {
  const key = f.url;
  if (!byUrl.has(key)) {
    byUrl.set(key, f);
    continue;
  }
  const existing = byUrl.get(key);
  // keep the earlier position
  if (f.pos < existing.pos) byUrl.set(key, f);
  else {
    // merge metadata if existing is missing
    byUrl.set(key, {
      ...existing,
      srcAlt: existing.srcAlt || f.srcAlt,
      srcTitle: existing.srcTitle || f.srcTitle,
      nearestHeading: existing.nearestHeading || f.nearestHeading,
      nearestHeadingLevel: existing.nearestHeadingLevel || f.nearestHeadingLevel,
      contextBefore: existing.contextBefore || f.contextBefore,
      contextAfter: existing.contextAfter || f.contextAfter,
    });
  }
}

let allImageObjs = Array.from(byUrl.values()).sort((a, b) => a.pos - b.pos);

// mainImage را اول قرار بده (اگر وجود دارد)
if (mainImage) {
  const idx = allImageObjs.findIndex((x) => x.url === mainImage);
  if (idx === -1) {
    allImageObjs.unshift({
      url: mainImage,
      pos: -1,
      srcAlt: "",
      srcTitle: "",
      nearestHeading: "",
      nearestHeadingLevel: "",
      contextBefore: "",
      contextAfter: "",
    });
  } else if (idx > 0) {
    const [it] = allImageObjs.splice(idx, 1);
    allImageObjs.unshift(it);
  }
}

// نهایتاً فقط URLها برای سازگاری قبلی
const allImages = allImageObjs.map((x) => x.url);

// ---- build named image objects (با role دقیق‌تر و hint) ----
const maxImages = 10;
const images = allImageObjs.slice(0, maxImages).map((img, i) => {
  const index = i + 1;
