// ---- VIDEOS extraction (همان منطق قبلی + پوسترهای غیر blank) ----
const metaVideoRegexes = [
  /<meta[^>]+property=["']og:video["'][^>]+content=["']([^"']+)["'][^>]*>/i,
  /<meta[^>]+property=["']og:video:url["'][^>]+content=["']([^"']+)["'][^>]*>/i,
  /<meta[^>]+name=["']twitter:player["'][^>]+content=["']([^"']+)["'][^>]*>/i,
  /"contentUrl"\s*:\s*"([^"]+)"/i,
  /"embedUrl"\s*:\s*"([^"]+)"/i,
];

let mainVideo = "";
for (const r of metaVideoRegexes) {
