const videoTagRegex = /<video\b[^>]*>([\s\S]*?)<\/video>/gi;
const videos = [];
const posters = [];

const getAttrFromTag = (tagHtml, name) => {
  const re = new RegExp(`${name}\\s*=\\s*["']([^"']+)["']`, "i");
  return re.exec(tagHtml)?.[1] || "";
};

let vmatch;
while ((vmatch = videoTagRegex.exec(text)) !== null) {
  const whole = vmatch[0];
  const inner = vmatch[1] || "";

  const vSrc = absolutize(getAttrFromTag(whole, "src"));
  if (vSrc) videos.push(vSrc);

  const poster = absolutize(getAttrFromTag(whole, "poster"));
  if (poster && !poster.toLowerCase().includes("/blank_")) posters.push(poster);

  const sourceTagRegex = /<source\b[^>]*>/gi;
  let sm;
  while ((sm = sourceTagRegex.exec(inner)) !== null) {
    const sTag = sm[0];
    const sSrc = absolutize(getAttrFromTag(sTag, "src"));
    const sType = (getAttrFromTag(sTag, "type") || "").toLowerCase();

    if ((sType && sType.startsWith("video/")) || (sSrc && /\.(mp4|webm|m3u8|mov|m4v)(\?|#|$)/i.test(sSrc))) {
      if (sSrc) videos.push(sSrc);
