    });
  } else {
    tagRecords.push({
      name: tagName,
      slug: desiredSlug,
      id: null,
      needsCreate: true
    });
  }
}

return tagRecords.map(r => ({ json: r }));

// اگر قبلاً درست ساخته شده (مثلاً خروجی مرحله‌ی GET یا create موفق)، دست نزن
if ($json?.slug && ($json?.id !== undefined && $json?.id !== null)) {
