// =========================
// 0) فقط ورودی همین نود (خروجی Normalizer)
// =========================
const inputRoot = $json;
const source = (inputRoot && typeof inputRoot === 'object') ? inputRoot : {};
const sourceMedia = Array.isArray(source.media) ? source.media : [];

// =========================
// 1) نودهای کمکی (فقط fallback اگر source نداد)
// =========================
const categoryNode = $items('Final Category')[0];
