const seriesNode = $items('Final Series')[0];
const seriesInfo = (seriesNode && seriesNode.json) ? seriesNode.json : {};

// Collect Tag IDs (fallback)
const tagItems = $items('Collect Tag IDs') || [];
const collectedTagIds = [];
for (let i = 0; i < tagItems.length; i++) {
  const j = (tagItems[i] && tagItems[i].json) ? tagItems[i].json : {};
  const arr = (j.tag_ids && Array.isArray(j.tag_ids))
    ? j.tag_ids
    : (j.tag_id != null ? [j.tag_id] : []);
  for (let k = 0; k < arr.length; k++) {
    if (arr[k] != null) collectedTagIds.push(arr[k]);
  }
}

// =========================
// helpers
// =========================
function toNumberOrDefault(value, def) {
  if (value === null || value === undefined || value === '') return def;
  const n = Number(value);
  return (isNaN(n) ? def : n);
}

function uniqNumbers(arr) {
  if (!Array.isArray(arr)) return [];
  const seen = new Set();
  const out = [];
  for (const v of arr) {
    const n = toNumberOrDefault(v, null);
    if (n === null) continue;
    if (!seen.has(n)) { seen.add(n); out.push(n); }
  }
  return out;
}

function normalizeTagArray(arr) { return uniqNumbers(arr); }
function isNonEmptyString(s) { return typeof s === 'string' && s.trim().length > 0; }
function normalizeVisibility(v) { return (v === 'public' || v === 'private') ? v : 'public'; }
function normalizeStatus(s) { return (s === 'draft' || s === 'published' || s === 'scheduled') ? s : 'draft'; }

// =========================
// 2) fallback image (اگر cover/og تو source نبود)
// =========================
function isValidImage(m) {
  if (!m || m.type !== 'image') return false;

  const url = (typeof m.url === 'string') ? m.url.trim() : '';
  if (!url || !(url.startsWith('http://') || url.startsWith('https://'))) return false;

  const w = toNumberOrDefault(m.width, null);
  const h = toNumberOrDefault(m.height, null);
  if (w === null || h === null) return false;
  if (w < 200 || h < 120) return false;
  if (w === 1 || h === 1) return false;

  const title = (typeof m.title === 'string') ? m.title.toLowerCase() : '';
  const urlLower = url.toLowerCase();
  if (title.includes('blank.gif') || urlLower.includes('blank')) return false;

  const id = toNumberOrDefault(m.id, null);
  if (id === null) return false;

  return true;
}

function pickLargestImage(images) {
  if (!images.length) return null;
  let best = images[0];
  for (let i = 1; i < images.length; i++) {
    const a = best, b = images[i];
    const aw = toNumberOrDefault(a.width, 0), bw = toNumberOrDefault(b.width, 0);
    const ah = toNumberOrDefault(a.height, 0), bh = toNumberOrDefault(b.height, 0);
    if (bw > aw || (bw === aw && bh > ah)) best = b;
  }
  return best;
}

const validImages = sourceMedia.filter(isValidImage);
const fallbackCover = pickLargestImage(validImages);
const fallbackCoverId = fallbackCover ? toNumberOrDefault(fallbackCover.id, null) : null;

// =========================
// 3) متن‌ها (همه از source)
// =========================
const title = isNonEmptyString(source.title) ? source.title : '';
const excerpt = isNonEmptyString(source.excerpt) ? source.excerpt : '';

const content =
  isNonEmptyString(source.content)
    ? source.content
    : (isNonEmptyString(source.summary_markdown) ? source.summary_markdown : '');

// =========================
// 4) تاریخ‌ها و status
// =========================
const published_at = source.published_at ? source.published_at : null;
const scheduled_at = source.scheduled_at ? source.scheduled_at : null;

let status = normalizeStatus(source.status);
if (scheduled_at) status = 'scheduled';
else if (published_at) status = 'published';
else status = normalizeStatus(status);

const visibility = normalizeVisibility(source.visibility);

// =========================
// 5) series/category/tag
// =========================
let series = 0;
if (source.series != null) series = toNumberOrDefault(source.series, 0);
else if (source.series_id != null) series = toNumberOrDefault(source.series_id, 0);
else if (seriesInfo && seriesInfo.series_id != null) series = toNumberOrDefault(seriesInfo.series_id, 0);
else if (seriesInfo && seriesInfo.id != null) series = toNumberOrDefault(seriesInfo.id, 0);

let category_id = 0;
if (source.category_id != null) category_id = toNumberOrDefault(source.category_id, 0);
else if (categoryInfo && categoryInfo.category_id != null) category_id = toNumberOrDefault(categoryInfo.category_id, 0);
else if (categoryInfo && categoryInfo.id != null) category_id = toNumberOrDefault(categoryInfo.id, 0);

let tag_ids = [];
if (Array.isArray(source.tag_ids) && source.tag_ids.length > 0) tag_ids = normalizeTagArray(source.tag_ids);
else tag_ids = normalizeTagArray(collectedTagIds);
tag_ids = uniqNumbers(tag_ids);

// =========================
// 6) SEO / slug / canonical
// =========================
const seo_title = isNonEmptyString(source.seo_title) ? source.seo_title : title;
const seo_description = isNonEmptyString(source.seo_description) ? source.seo_description : excerpt;

const slug = isNonEmptyString(source.slug) ? source.slug : '';
const canonical_url = (typeof source.canonical_url === 'string') ? source.canonical_url : '';

// =========================
// 7) cover/og
// =========================
let cover_media_id = toNumberOrDefault(source.cover_media_id, null);
if (cover_media_id === null && fallbackCoverId !== null) cover_media_id = fallbackCoverId;

let og_image_id = toNumberOrDefault(source.og_image_id, null);
if (og_image_id === null && cover_media_id !== null) og_image_id = cover_media_id;

// =========================
// 8) body نهایی
// =========================
const body = {
  title,
  excerpt,
  content,
  status,
  visibility,
  published_at,
  scheduled_at,
  series,
  seo_title,
  seo_description,
  slug,
  canonical_url,
  tag_ids,
  category_id,
  cover_media_id,
  og_image_id,
};

return [{ json: body }];

