const media = [];

for (const item of items) {
  const j = item.json ?? {};

  const id = j.id ?? null;
  const url = j.url || j.file || j.file_url || j.original || j.download_url || null;

  // اطلاعات مهم (به‌صورت امن/تمیز)
  const type = j.type ?? null;
  const mime = j.mime ?? null;
  const width = j.width ?? null;
  const height = j.height ?? null;
  const sizeBytes = j.size_bytes ?? null;
  const duration = j.duration ?? null;
  const storageKey = j.storage_key ?? null;
  const uploadedBy = j.uploaded_by ?? null;
  const createdAt = j.created_at ?? null;

  // alt_text: حذف "=" ابتدای متن (اگر وجود داشت) + trim
  let altText = j.alt_text ?? null;
  if (typeof altText === "string") {
    altText = altText.trim();
    if (altText.startsWith("=")) altText = altText.slice(1).trim();
    if (!altText) altText = null;
  }

  // title: decode ساده برای %27 و...
  let title = j.title ?? null;
  if (typeof title === "string") {
    title = title.trim();
    try { title = decodeURIComponent(title); } catch (_) {}
    if (!title) title = null;
  }

  // اگر اصلاً url یا id نداریم، بیخیال شو (قابل تغییر)
  if (id == null && !url) continue;

  media.push({
    id,
    url,
    type,
    mime,
    width,
    height,
    sizeBytes,
    duration,
    storageKey,
    title,
    altText,
    uploadedBy,
    createdAt,
  });
}

// خروجی‌های کمکی هم کنار media برگردون
const mediaIds = media.map(m => m.id).filter(v => v != null);
const mediaUrls = media.map(m => m.url).filter(Boolean);

return [
  {
    json: {
      media,       // لیست کامل اطلاعات مهم
      mediaIds,    // فقط id ها
      mediaUrls,   // فقط url ها
      count: media.length,
    },
  },
];

