function slugifyAscii(s) {
  return (s ?? "")
    .toString()
    .trim()
    .toLowerCase()
    // allow only a-z 0-9 _ -
    .replace(/[^a-z0-9_-]+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "");
}

for (const item of $input.all()) {
  const name = (item.json.name ?? "").toString().trim();
  const existingSlug = (item.json.slug ?? "").toString().trim();

  let slug = slugifyAscii(existingSlug.length ? existingSlug : name);

  // If name was Persian-only, slug becomes empty. Create a safe fallback.
  if (!slug) {
    // stable-ish fallback using a tiny hash of the name
    let hash = 0;
    for (let i = 0; i < name.length; i++) hash = (hash * 31 + name.charCodeAt(i)) >>> 0;
    slug = `tag-${hash.toString(16)}`; // e.g. tag-7a3f2c1
  }

  item.json.slug = slug;
}

return $input.all();

// n8n Code node (JavaScript)
// هدف: استخراج JSON معتبر از خروجی AI که ممکنه داخل output/text باشد یا داخل ```json ... ``` باشد.

const candidates = [
  $json?.output,
  $json?.text,
  $json?.response,
  $json?.data,
  $json,
];

const toStr = (v) => (typeof v === "string" ? v : JSON.stringify(v));

let raw = "";
for (const c of candidates) {
  if (!c) continue;
  const s = toStr(c);
  // اگر شبیه JSON یا شامل ``` یا شامل { } بود، انتخابش کن
  if (s.includes("{") && s.includes("}")) { raw = s; break; }
}

raw = String(raw || "").trim();
if (!raw) throw new Error("No AI output found to parse");

// 1) حذف code fence ها
let cleaned = raw
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/```$/i, "")
  .trim();

// 2) اگر داخل یک رشته، JSON وجود دارد (قبل/بعدش متن هست)، فقط اولین JSON object را جدا کن
const extractFirstJsonObject = (s) => {
  const start = s.indexOf("{");
  if (start < 0) return "";
  let depth = 0;
  let inStr = false;
  let esc = false;

  for (let i = start; i < s.length; i++) {
    const ch = s[i];

    if (inStr) {
      if (esc) esc = false;
      else if (ch === "\\") esc = true;
      else if (ch === '"') inStr = false;
      continue;
    } else {
      if (ch === '"') { inStr = true; continue; }
      if (ch === "{") depth++;
      if (ch === "}") depth--;
      if (depth === 0) return s.slice(start, i + 1);
    }
  }
  return "";
};

const jsonSlice = cleaned.startsWith("{") ? cleaned : extractFirstJsonObject(cleaned);
if (!jsonSlice) throw new Error("Could not locate a JSON object in AI output");

// 3) پارس JSON
let parsed;
try {
  parsed = JSON.parse(jsonSlice);
} catch (e) {
  throw new Error("AI output JSON.parse failed: " + e.message + "\n---\n" + jsonSlice.slice(0, 4000));
}

// 4) (اختیاری ولی خیلی مهم) ولیدیشن ضد هالوسینیشن URL
// اگر input اصلی را هم کنار AI داری، این چک را روشن کن.
// اینجا فرض می‌کنیم input images در $json.input_images یا در $json.original.images بوده.
// اگر چنین فیلدی ندارید، این بخش را کامنت کنید.

const inputImages =
  $json?.original?.images ||
  $json?.input_images ||
  null;

if (inputImages && Array.isArray(inputImages) && Array.isArray(parsed.images)) {
  const allowed = new Set(inputImages.map((x) => x?.url).filter(Boolean));
  for (const it of parsed.images) {
    if (it?.url && !allowed.has(it.url)) {
      throw new Error("AI returned a URL that is not in input: " + it.url);
    }
  }
}

// 5) خروجی نهایی
return [{ json: parsed }];

