parameters.jsCode:
/**
 * Advanced Generic Article Extractor (n8n Code node)
 *
 * Accepts almost any input shape:
 * - HTML string
 * - object containing html/body/data/response/text/output
 * - array of such objects
 * - nested structures (deep scan)
 * - already-extracted article JSON (normalize)
 *
 * Output (always):
 * { title, description, author, published_at, content_text, content_html, word_count, method, warnings }
 */

function isPlainObject(x) {
  return Object.prototype.toString.call(x) === '[object Object]';
}

function safeString(x) {
  try {
    if (x == null) return '';
    if (typeof x === 'string') return x;
    if (typeof x === 'number' || typeof x === 'boolean') return String(x);
    return JSON.stringify(x);
  } catch {
    try { return String(x); } catch { return ''; }
  }
}

/** Minimal (but useful) HTML entity decoding */
function decodeHtmlEntities(str) {
  if (!str) return '';
  return String(str)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#039;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(parseInt(n, 10)));
}

function stripTags(html) {
  if (!html) return '';
  return decodeHtmlEntities(
    String(html)
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/p\s*>/gi, '\n')
      .replace(/<\/h\d\s*>/gi, '\n')
      .replace(/<\/li\s*>/gi, '\n')
      .replace(/<li[^>]*>/gi, '• ')
      .replace(/<[^>]+>/g, ' ')
      .replace(/[ \t]+\n/g, '\n')
      .replace(/\n{3,}/g, '\n\n')
      .replace(/[ \t]{2,}/g, ' ')
      .trim()
  );
}

function wordCount(text) {
  if (!text) return 0;
  return (String(text).trim().match(/\S+/g) || []).length;
}

function looksLikeHtml(s) {
  if (!s) return false;
  const t = String(s).trim();
  // fast checks
  if (t.startsWith('<!doctype') || t.startsWith('<html') || t.startsWith('<head') || t.startsWith('<body')) return true;
  // general tag presence
  return /<\/?(html|head|body|article|main|p|div|span|script|style)\b/i.test(t);
}

function looksLikeExtractedArticleJson(obj) {
  if (!isPlainObject(obj)) return false;
  // Heuristic: keys we expect from extracted article JSON
  const keys = Object.keys(obj);
  const hasCore = keys.includes('content_text') || keys.includes('content_html');
  const hasMeta = keys.includes('title') || keys.includes('description') || keys.includes('author') || keys.includes('published_at');
  return hasCore && hasMeta;
}

/**
 * Deep scan any structure for:
 * - HTML-ish string
 * - large text blocks (fallback)
 */
function deepFindCandidates(root, maxNodes = 2000) {
  const htmlCandidates = [];
  const textCandidates = [];
  const warnings = [];

  const seen = new Set();
  const q = [root];
  let steps = 0;

  while (q.length && steps++ < maxNodes) {
    const cur = q.shift();
    if (cur == null) continue;

    if (typeof cur === 'string') {
      const s = cur.trim();
      if (!s) continue;

      if (looksLikeHtml(s)) htmlCandidates.push(s);
      else if (s.length > 300) textCandidates.push(s);
      continue;
    }

    if (typeof cur === 'number' || typeof cur === 'boolean') continue;

    // Avoid cycles
    if (typeof cur === 'object') {
      if (seen.has(cur)) continue;
      seen.add(cur);
    }

    if (Array.isArray(cur)) {
      for (const v of cur) q.push(v);
      continue;
    }

    if (isPlainObject(cur)) {
      // strongly weighted fields first
      const directFields = [
        'html','body','data','response','text','output','content','contents','document','page',
        'article','articleHtml','articleHTML','raw','rawHtml','rawHTML','result'
      ];

      for (const k of directFields) {
        if (cur[k] != null) {
          if (typeof cur[k] === 'string') {
            const s = cur[k].trim();
            if (looksLikeHtml(s)) htmlCandidates.push(s);
            else if (s.length > 300) textCandidates.push(s);
          } else {
            q.push(cur[k]);
          }
        }
      }

      // then traverse all keys
      for (const [k, v] of Object.entries(cur)) {
        // skip very common giant binary-ish fields
        if (/^(base64|image|binary|buffer)$/i.test(k)) continue;
        if (v == null) continue;
        if (typeof v === 'string') {
          const s = v.trim();
          if (!s) continue;
          if (looksLikeHtml(s)) htmlCandidates.push(s);
          else if (s.length > 300) textCandidates.push(s);
        } else {
          q.push(v);
        }
      }
    }
  }

  if (steps >= maxNodes) warnings.push(`deep-scan capped at ${maxNodes} nodes (input too large or deeply nested)`);

  // Prefer biggest/most likely candidates
  htmlCandidates.sort((a,b) => b.length - a.length);
  textCandidates.sort((a,b) => b.length - a.length);

  return { htmlCandidates, textCandidates, warnings };
}

/**
 * Picks the best "source" input:
 * - If already extracted JSON -> return normalized object marker
 * - Else find HTML (best)
 * - Else find large text (fallback)
 */
function pickInput(raw) {
  const warnings = [];

  // Already-extracted JSON in $json
  if (looksLikeExtractedArticleJson(raw)) {
    return { kind: 'extracted-json', value: raw, warnings };
  }

  // Common n8n wrappers
  // sometimes $json might be something like { items: [ { json: {...} } ] } but in Code node $json is each item.json already.
  // We'll still handle arrays & nested.
  const { htmlCandidates, textCandidates, warnings: scanWarnings } = deepFindCandidates(raw);
  warnings.push(...scanWarnings);

  if (htmlCandidates.length) return { kind: 'html', value: htmlCandidates[0], warnings };
  if (textCandidates.length) return { kind: 'text', value: textCandidates[0], warnings };

  // Last resort: stringify
  const s = safeString(raw);
  if (looksLikeHtml(s)) return { kind: 'html', value: s, warnings: [...warnings, 'picked from JSON.stringify'] };
  if (s.length > 300) return { kind: 'text', value: s, warnings: [...warnings, 'picked from JSON.stringify'] };

  return { kind: 'empty', value: '', warnings: [...warnings, 'no suitable input found'] };
}

function firstMatch(re, str) {
  const m = re.exec(str);
  return m ? m[1] : '';
}

function cleanHtml(html) {
  return String(html)
    .replace(/<!doctype[^>]*>/ig, '')
    .replace(/<script[\s\S]*?<\/script>/ig, ' ')
    .replace(/<style[\s\S]*?<\/style>/ig, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/ig, ' ')
    .replace(/<svg[\s\S]*?<\/svg>/ig, ' ')
    .replace(/<iframe[\s\S]*?<\/iframe>/ig, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<(header|footer|nav|aside)\b[\s\S]*?<\/\1>/ig, ' ');
}

function extractMeta(html) {
  const title =
    firstMatch(/<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)["']/i, html) ||
    firstMatch(/<meta[^>]+name=["']twitter:title["'][^>]+content=["']([^"']+)["']/i, html) ||
    decodeHtmlEntities(firstMatch(/<title[^>]*>([\s\S]*?)<\/title>/i, html)).trim();

  const description =
    firstMatch(/<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']+)["']/i, html) ||
    firstMatch(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)["']/i, html) ||
    firstMatch(/<meta[^>]+name=["']twitter:description["'][^>]+content=["']([^"']+)["']/i, html);

  const author =
    firstMatch(/<meta[^>]+name=["']author["'][^>]+content=["']([^"']+)["']/i, html) ||
    firstMatch(/<meta[^>]+property=["']article:author["'][^>]+content=["']([^"']+)["']/i, html) ||
    firstMatch(/<meta[^>]+name=["']parsely-author["'][^>]+content=["']([^"']+)["']/i, html);

  const published =
    firstMatch(/<meta[^>]+property=["']article:published_time["'][^>]+content=["']([^"']+)["']/i, html) ||
    firstMatch(/<meta[^>]+property=["']og:updated_time["'][^>]+content=["']([^"']+)["']/i, html) ||
    firstMatch(/<meta[^>]+name=["']date["'][^>]+content=["']([^"']+)["']/i, html) ||
    firstMatch(/<time[^>]+datetime=["']([^"']+)["'][^>]*>/i, html);

  return {
    title: decodeHtmlEntities(title || '').trim(),
    description: decodeHtmlEntities(description || '').trim(),
    author: decodeHtmlEntities(author || '').trim(),
    published_at: decodeHtmlEntities(published || '').trim(),
  };
}

function normalizeJsonLdNode(n) {
  if (!n || typeof n !== 'object') return null;
  const type = n['@type'];
  const tStr = Array.isArray(type) ? type.map(String).join(' ') : String(type || '');
  const isArticle = /article|newsarticle|blogposting|report|review/i.test(tStr);

  if (!isArticle) return null;

  // Candidates for body-like fields
  const body =
    (typeof n.articleBody === 'string' && n.articleBody) ||
    (typeof n.text === 'string' && n.text) ||
    (typeof n.description === 'string' && n.description) ||
    '';

  const headline =
    (typeof n.headline === 'string' && n.headline) ||
    (typeof n.name === 'string' && n.name) ||
    '';

  let author = '';
  // author can be string/object/array
  if (typeof n.author === 'string') author = n.author;
  else if (Array.isArray(n.author)) {
    const a0 = n.author.find(x => typeof x === 'string' || (x && typeof x === 'object'));
    if (typeof a0 === 'string') author = a0;
    else if (a0 && typeof a0 === 'object') author = a0.name || a0['@id'] || '';
  } else if (n.author && typeof n.author === 'object') {
    author = n.author.name || n.author['@id'] || '';
  }

  const date =
    n.datePublished || n.dateCreated || n.dateModified || '';

  const desc = (typeof n.description === 'string' && n.description) || '';

  return {
    title: decodeHtmlEntities(headline).trim(),
    description: decodeHtmlEntities(desc).trim(),
    author: decodeHtmlEntities(author).trim(),
    published_at: decodeHtmlEntities(String(date || '')).trim(),
    body: decodeHtmlEntities(String(body || '')).trim(),
  };
}

function extractFromJsonLd(originalHtml) {
  const scripts = [...String(originalHtml).matchAll(/<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/ig)]
    .map(m => m[1].trim())
    .filter(Boolean);

  let best = null;

  for (const s of scripts) {
    let parsed;
    try { parsed = JSON.parse(s); } catch { continue; }

    const nodes = Array.isArray(parsed) ? parsed : [parsed];
    const expanded = [];
    for (const n of nodes) {
      if (n && typeof n === 'object' && Array.isArray(n['@graph'])) expanded.push(...n['@graph']);
      else expanded.push(n);
    }

    for (const n of expanded) {
      const norm = normalizeJsonLdNode(n);
      if (!norm) continue;

      const score = (norm.body?.length || 0) + (norm.title ? 200 : 0) + (norm.published_at ? 50 : 0);
      if (!best || score > best.score) best = { ...norm, score };
    }
  }

  if (best && best.body && best.body.length > 250) {
    return best;
  }
  return null;
}

function extractArticleTag(html) {
  const m = /<article\b[^>]*>([\s\S]*?)<\/article>/i.exec(html);
  return m ? m[1] : '';
}
function extractMainTag(html) {
  const m = /<main\b[^>]*>([\s\S]*?)<\/main>/i.exec(html);
  return m ? m[1] : '';
}

function sanitizeForContent(htmlFragment) {
  return String(htmlFragment)
    .replace(/<(form|button)\b[\s\S]*?<\/\1>/ig, ' ')
    .replace(/<div\b[^>]*class=["'][^"']*(comment|share|social|newsletter|subscribe|related|promo|ad|advert|cookie|nav|footer|header)[^"']*["'][^>]*>[\s\S]*?<\/div>/ig, ' ')
    .replace(/<ul\b[^>]*class=["'][^"']*(nav|menu)[^"']*["'][^>]*>[\s\S]*?<\/ul>/ig, ' ');
}

function scoreBlock(htmlFragment) {
  const frag = String(htmlFragment || '');
  const pCount = (frag.match(/<p\b/gi) || []).length;
  const liCount = (frag.match(/<li\b/gi) || []).length;
  const aCount = (frag.match(/<a\b/gi) || []).length;
  const hCount = (frag.match(/<h[1-6]\b/gi) || []).length;

  const text = stripTags(frag);
  const len = text.length;

  // Penalize link density and very short blocks
  const linkPenalty = Math.min(0.7, aCount / Math.max(1, pCount + liCount + 1));
  const shortPenalty = len < 400 ? (400 - len) : 0;

  return (len * 1.0) + (pCount * 220) + (liCount * 90) + (hCount * 60) - (len * linkPenalty) - shortPenalty;
}

function extractByHeuristics(html) {
  const candidates = [];

  const article = extractArticleTag(html);
  if (article) candidates.push({ method: 'article-tag', html: article });

  const main = extractMainTag(html);
  if (main) candidates.push({ method: 'main-tag', html: main });

  const patterns = [
    /<div\b[^>]+id=["'][^"']*(content|article|post|story|body|main|page|entry)[^"']*["'][^>]*>([\s\S]*?)<\/div>/ig,
    /<div\b[^>]+class=["'][^"']*(content|article|post|story|body|main|entry|read|text|copy|markdown|rich-text)[^"']*["'][^>]*>([\s\S]*?)<\/div>/ig,
    /<section\b[^>]+class=["'][^"']*(content|article|post|story|body|entry|main)[^"']*["'][^>]*>([\s\S]*?)<\/section>/ig,
  ];

  for (const re of patterns) {
    let m;
    let guard = 0;
    while ((m = re.exec(html)) && guard++ < 60) {
      const frag = m[2] || m[1] || '';
      if (frag && frag.length > 600) candidates.push({ method: 'container-heuristic', html: frag });
    }
  }

  // If still nothing, consider the whole doc (but sanitized later)
  if (!candidates.length) candidates.push({ method: 'fallback-whole-doc', html });

  let best = null;
  for (const c of candidates) {
    const s = scoreBlock(c.html);
    if (!best || s > best.score) best = { ...c, score: s };
  }
  return best;
}

function extractReadableHtml(cleanedHtml) {
  const picked = extractByHeuristics(cleanedHtml);
  const pruned = sanitizeForContent(picked.html);

  const safe = String(pruned)
    .replace(/<(div|span)\b[^>]*>/ig, '\n')
    .replace(/<\/(div|span)\s*>/ig, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  const text = stripTags(safe);

  if (text.length < 250) {
    const fallbackText = stripTags(cleanedHtml);
    return { method: picked.method + '+fallback-strip', content_html: '', content_text: fallbackText };
  }

  return { method: picked.method, content_html: safe, content_text: text };
}

function normalizeOutput(base, extracted) {
  const title = (extracted.title || base.title || '').trim();
  const description = (extracted.description || base.description || '').trim();
  const author = (extracted.author || base.author || '').trim();
  const published_at = (extracted.published_at || base.published_at || '').trim();
  const content_text = (extracted.content_text || '').trim();
  const content_html = (extracted.content_html || '').trim();

  return {
    title,
    description,
    author,
    published_at,
    content_text,
    content_html,
    word_count: wordCount(content_text),
  };
}

// -------------------- main --------------------
const raw = $json;
const picked = pickInput(raw);

const empty = {
  title: '',
  description: '',
  author: '',
  published_at: '',
  content_text: '',
  content_html: '',
  word_count: 0,
  method: 'no-input',
  warnings: picked.warnings || [],
};

// Case 1: already extracted JSON -> normalize and return
if (picked.kind === 'extracted-json') {
  const obj = picked.value || {};
  const out = normalizeOutput(
    { title: '', description: '', author: '', published_at: '' },
    {
      title: safeString(obj.title || ''),
      description: safeString(obj.description || ''),
      author: safeString(obj.author || ''),
      published_at: safeString(obj.published_at || ''),
      content_text: safeString(obj.content_text || ''),
      content_html: safeString(obj.content_html || ''),
    }
  );

  return [{
    json: {
      ...out,
      method: safeString(obj.method || 'normalize(extracted-json)'),
      warnings: (picked.warnings || []).concat(obj.warnings || []),
    }
  }];
}

// Case 2: plain text input (no HTML) -> return as content_text
if (picked.kind === 'text') {
  const text = String(picked.value || '').trim();
  const out = normalizeOutput({ title: '', description: '', author: '', published_at: '' }, { content_text: text, content_html: '' });

  const warnings = (picked.warnings || []).concat(['input was not HTML; treated as plain text']);
  return [{
    json: {
      ...out,
      method: 'plain-text',
      warnings,
    }
  }];
}

// Case 3: HTML -> full extraction
if (picked.kind === 'html') {
  const html = String(picked.value || '');

  if (html.trim().length < 50) {
    return [{ json: { ...empty, method: 'no-html-or-too-short' } }];
  }

  const meta = extractMeta(html);

  // JSON-LD best path
  const jsonLd = extractFromJsonLd(html);
  if (jsonLd && jsonLd.body) {
    // Merge meta + json-ld (json-ld wins if it has values)
    const mergedMeta = {
      title: jsonLd.title || meta.title,
      description: jsonLd.description || meta.description,
      author: jsonLd.author || meta.author,
      published_at: jsonLd.published_at || meta.published_at,
    };

    const body = jsonLd.body.trim();
    const out = normalizeOutput(mergedMeta, { content_text: body, content_html: '' });

    const warnings = (picked.warnings || []);
    if (out.content_text.length < 400) warnings.push('json-ld body was short; site may be truncating articleBody/text');

    return [{
      json: {
        ...out,
        method: 'json-ld(articleBody|text|description)',
        warnings,
      }
    }];
  }

  // Heuristic extraction
  const cleaned = cleanHtml(html);
  const extracted = extractReadableHtml(cleaned);

  const out = normalizeOutput(meta, extracted);

  const warnings = (picked.warnings || []);
  if (out.content_text.length < 300) warnings.push('extracted text is short; input may be partial HTML or JS-rendered page');
  if (!out.title) warnings.push('missing title');
  if (!out.published_at) warnings.push('missing published_at');

  return [{
    json: {
      ...out,
      method: extracted.method,
      warnings,
    }
  }];
}

// Fallback: nothing
return [{ json: empty }];

