const agent2 = $('AI Agent2').first().json;
const raw = agent2.output || agent2.text || agent2.response || agent2;

// Excerpt from previous node (current incoming item)
const previousExcerpt = (typeof $json.excerpt === 'string' ? $json.excerpt : '').trim();

function collapseSpaces(s) {
  return (s || '')
    .replace(/[\r\n]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function stripCodeFences(s) {
  if (typeof s !== 'string') return '';
  let t = s.trim();
  t = t.replace(/^```[a-zA-Z0-9_-]*\s*/m, '');
  t = t.replace(/```$/m, '');
  t = t.replace(/```/g, '');
  t = t.replace(/^json\s*/i, '');
  return t.trim();
}

function extractSummaryMarkdownFromBrokenJsonString(s) {
  if (typeof s !== 'string') return '';
  const t = stripCodeFences(s);

  const m = t.match(/"summary_markdown"\s*:\s*"((?:\\.|[^"\\])*)"/);
  if (!m) return '';

  try {
    return JSON.parse(`"${m[1]}"`);
  } catch (e) {
    return m[1]
      .replace(/\\"/g, '"')
      .replace(/\\n/g, '\n')
      .replace(/\\r/g, '\r')
      .replace(/\\t/g, '\t')
      .replace(/\\\\/g, '\\');
  }
}

function sanitizePossiblyJsonishText(s) {
  if (typeof s !== 'string') return '';
  const cleaned = stripCodeFences(s);

  if (cleaned.includes('"summary_markdown"')) {
    const extracted = extractSummaryMarkdownFromBrokenJsonString(cleaned);
    if (extracted) return extracted;
  }

  if (/^[\[{]/.test(cleaned)) {
    try {
      const obj = JSON.parse(cleaned);
      if (obj && typeof obj === 'object') {
        if (typeof obj.excerpt === 'string') return stripCodeFences(obj.excerpt);
        if (typeof obj.seo_description === 'string') return stripCodeFences(obj.seo_description);
        if (typeof obj.summary_markdown === 'string') return obj.summary_markdown;
        if (typeof obj.summary === 'string') return obj.summary;
      }
    } catch (e) {}
  }

  return cleaned;
}

let meta;
try {
  meta = typeof raw === 'string' ? JSON.parse(stripCodeFences(raw)) : raw;
} catch (e) {
  const fallbackSummary = typeof raw === 'string' ? raw : JSON.stringify(raw);
  meta = {
    summary_markdown: fallbackSummary,
    title: 'خلاصه مهم‌ترین خبرهای بازی امروز',
    seo_title: 'خلاصه مهم‌ترین خبرهای بازی امروز',
    seo_description: '',
    category_slug: 'game-news',
    series_slug: 'daily-digest',
    tags: ['اخبار بازی'],
    focus_keywords: [],
    chosen_index: 0,
    reason: 'fallback – JSON parse error'
  };
}

const summary = (meta.summary_markdown || meta.summary || '').toString().trim();
const baseExcerptFromSummary = collapseSpaces(summary).slice(0, 220);

let excerptCandidate =
  (typeof meta.excerpt === 'string' && meta.excerpt.trim())
    ? meta.excerpt
    : (previousExcerpt || baseExcerptFromSummary);

excerptCandidate = collapseSpaces(sanitizePossiblyJsonishText(excerptCandidate)).slice(0, 220);
const excerpt = excerptCandidate || baseExcerptFromSummary;

const title =
  (typeof meta.title === 'string' && meta.title.trim())
    ? meta.title.trim()
    : 'خلاصه مهم‌ترین خبرهای بازی امروز';

const seoTitle =
  (typeof meta.seo_title === 'string' && meta.seo_title.trim())
    ? collapseSpaces(sanitizePossiblyJsonishText(meta.seo_title)).slice(0, 60)
    : title;

let seoDescCandidate =
  (typeof meta.seo_description === 'string' && meta.seo_description.trim())
    ? meta.seo_description
    : excerpt;

seoDescCandidate = collapseSpaces(sanitizePossiblyJsonishText(seoDescCandidate)).slice(0, 160);
const seoDescription = seoDescCandidate || excerpt;

const titleVariants = Array.isArray(meta.title_variants) ? meta.title_variants : [];
const focusKeywords = Array.isArray(meta.focus_keywords) ? meta.focus_keywords : [];
const chosenIndex = Number.isInteger(meta.chosen_index) ? meta.chosen_index : 0;

return [{
  json: {
    summary_markdown: summary,
    title,
    title_variants: titleVariants,
    excerpt,
    seo_title: seoTitle,
    seo_description: seoDescription,
    category_slug: meta.category_slug || 'game-news',
    series_slug: meta.series_slug || 'daily-digest',
    tags: Array.isArray(meta.tags) ? meta.tags : ['اخبار بازی'],
    focus_keywords: focusKeywords,
    chosen_index: chosenIndex,
    selection_reason: meta.reason || ''
  }
}];

