/**
 * Normalizer (Single Node)
 * هدف: تبدیل هر نوع خروجی (آرایه/کدفنس/output/...) به یک JSON object واحد و خام.
 */

const input = $json;

// --- utils ---
function safeJsonParse(s) {
  try { return JSON.parse(s); } catch { return null; }
}

function stripCodeFences(s) {
  if (typeof s !== 'string') return '';
  return s
    .replace(/^\s*```(?:json)?\s*/i, '')
    .replace(/\s*```\s*$/i, '')
    .trim();
}

function extractFirstJson(s) {
  if (typeof s !== 'string') return null;
  const t = stripCodeFences(s);

  // direct parse
  const direct = safeJsonParse(t);
  if (direct && typeof direct === 'object') return direct;

  // attempt to slice first {...}
  const start = t.indexOf('{');
  const end = t.lastIndexOf('}');
  if (start !== -1 && end !== -1 && end > start) {
    const candidate = t.slice(start, end + 1);
    const parsed = safeJsonParse(candidate);
    if (parsed && typeof parsed === 'object') return parsed;
  }
  return null;
}

function looksLikePostSchema(obj) {
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return false;
  // چند کلید هسته‌ای که معمولاً همیشه هست
  return (
    typeof obj.title === 'string' ||
    typeof obj.content === 'string' ||
    typeof obj.excerpt === 'string' ||
    typeof obj.slug === 'string'
  );
}

function normalizeAnyShape(x) {
  // حالت A: خود ورودی یک آبجکت آماده است
  if (looksLikePostSchema(x)) return x;

  // حالت B: ورودی آرایه است => آیتم اول
  const root = Array.isArray(x) ? (x[0] || {}) : (x || {});

  // اگر root خودش آماده است
  if (looksLikePostSchema(root)) return root;

  // حالت C: wrapper رایج { output: "```json ...```" }
  if (root && typeof root.output === 'string') {
    const parsed = extractFirstJson(root.output);
    if (looksLikePostSchema(parsed) || (parsed && typeof parsed === 'object')) return parsed;
  }

  // حالت D: { output: { ... } }
  if (root && root.output && typeof root.output === 'object' && !Array.isArray(root.output)) {
    return root.output;
  }

  // حالت E: بعضی نودها { data: ... } یا { result: ... } میدن (اگر خواستی نگه داریم)
  // این بخش اختیاریه ولی کمک می‌کنه:
  if (root && root.data && typeof root.data === 'object' && !Array.isArray(root.data)) return root.data;
  if (root && root.result && typeof root.result === 'object' && !Array.isArray(root.result)) return root.result;

  // fallback خالی
  return {};
}

const normalized = normalizeAnyShape(input);
return [{ json: normalized }];
